    {
      "id": 1,
      "claim": "Calculate the initial number of occupied beds.",
      "evidence": "Total capacity is 1000 beds, and 1/5 are occupied. 1000 * (1/5) = 200 occupied beds.",
      "weight": 0.15,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "Determine the total number of days in 2 weeks.",
      "evidence": "1 week has 7 days, so 2 weeks have 2 * 7 = 14 days.",
      "weight": 0.15,
      "depends_on": []
    },
    {
      "id": 3,
      "claim": "Calculate the total number of new patients admitted over 2 weeks.",
      "evidence": "50 patients are admitted each day for 14 days. 50 * 14 = 700 new patients.",
      "weight": 0.2,
      "depends_on": [
        2
      ]
    },
    {
      "id": 4,
      "claim": "Calculate the total number of occupied beds after 2 weeks.",
      "evidence": "Initial occupied beds plus new admissions: 200 + 700 = 900 occupied beds.",
      "weight": 0.25,
      "depends_on": [
        1,
        3
      ]
    },
    {
      "id": 5,
      "claim": "Calculate the final number of unoccupied beds.",
      "evidence": "Total capacity minus total occupied beds: 1000 - 900 = 100 unoccupied beds.",
      "weight": 0.25,
      "depends_on": [
        4
      ]
    }
  ],
  "answer": "100",
  "confidence": 1.0,
  "considered": [
    {
      "answer": "0",
      "reason_rejected": "This would imply the hospital is full. However, 200 (initial) + 700 (new) = 900, which is less than the 1000 capacity."
    },
    {
      "answer": "800",
